using FindUpTo.Pos.Server.Data;
using Microsoft.EntityFrameworkCore;
namespace FindUpTo.Pos.Server.Endpoints;
public static class ReportEndpoints
{
 public static void MapReportEndpoints(this WebApplication app)
 {
  app.MapGet("/api/reports/sales", async (CoreDbContext db, DateTime? fromUtc, DateTime? toUtc) => { var from=fromUtc??DateTime.UtcNow.Date; var to=toUtc??DateTime.UtcNow; if(to<from)return Results.BadRequest("toUtc must be greater than or equal to fromUtc."); var orders=await db.Orders.AsNoTracking().Where(x=>x.CreatedAtUtc>=from&&x.CreatedAtUtc<=to&&x.Status!="Cancelled").ToListAsync(); var payments=await db.Payments.AsNoTracking().Where(x=>x.CreatedAtUtc>=from&&x.CreatedAtUtc<=to&&x.Status=="Paid").ToListAsync(); return Results.Ok(new {fromUtc=from,toUtc=to,orderCount=orders.Count,subtotal=orders.Sum(x=>x.Subtotal),tax=orders.Sum(x=>x.Tax),grossSales=orders.Sum(x=>x.Total),paidAmount=payments.Sum(x=>x.AmountPaid),paymentsByMethod=payments.GroupBy(x=>x.Method).Select(g=>new {method=g.Key,amount=g.Sum(x=>x.AmountPaid),count=g.Count()}).OrderByDescending(x=>x.amount)}); }).RequireAuthorization(p=>p.RequireRole("Owner","Manager","Admin"));
  app.MapGet("/api/reports/products", async (CoreDbContext db, DateTime? fromUtc, DateTime? toUtc) => { var from=fromUtc??DateTime.UtcNow.Date; var to=toUtc??DateTime.UtcNow; if(to<from)return Results.BadRequest("toUtc must be greater than or equal to fromUtc."); var rows=await db.OrderItems.AsNoTracking().Where(x=>db.Orders.Any(o=>o.Id==x.PosOrderId&&o.CreatedAtUtc>=from&&o.CreatedAtUtc<=to&&o.Status!="Cancelled")).GroupBy(x=>new{x.ProductId,x.ProductName}).Select(g=>new{productId=g.Key.ProductId,productName=g.Key.ProductName,quantity=g.Sum(x=>x.Quantity),sales=g.Sum(x=>x.LineTotal)}).OrderByDescending(x=>x.sales).Take(100).ToListAsync(); return Results.Ok(rows); }).RequireAuthorization(p=>p.RequireRole("Owner","Manager","Admin"));
  app.MapGet("/api/reports/purchasing", async (CoreDbContext db, DateTime? fromUtc, DateTime? toUtc) => { var from=fromUtc??DateTime.UtcNow.Date; var to=toUtc??DateTime.UtcNow; if(to<from)return Results.BadRequest("toUtc must be greater than or equal to fromUtc."); var items=await db.PurchaseOrderItems.AsNoTracking().Where(x=>db.PurchaseOrders.Any(o=>o.Id==x.PurchaseOrderId&&o.CreatedAtUtc>=from&&o.CreatedAtUtc<=to)).ToListAsync(); var rows=items.GroupBy(x=>x.ProductId).Select(g=>new{productId=g.Key,productName=g.First().ProductName,quantityOrdered=g.Sum(x=>x.QuantityOrdered),quantityReceived=g.Sum(x=>x.QuantityReceived),spend=Math.Round(g.Sum(x=>x.QuantityReceived*x.UnitCost),2)}).OrderByDescending(x=>x.spend).Take(500).ToList(); return Results.Ok(new{fromUtc=from,toUtc=to,purchaseOrderCount=await db.PurchaseOrders.CountAsync(x=>x.CreatedAtUtc>=from&&x.CreatedAtUtc<=to),totalSpend=Math.Round(rows.Sum(x=>x.spend),2),rows}); }).RequireAuthorization(p=>p.RequireRole("Owner","Manager","Admin"));
  app.MapGet("/api/reports/profit", async (CoreDbContext db, DateTime? fromUtc, DateTime? toUtc) => { var from=fromUtc??DateTime.UtcNow.Date; var to=toUtc??DateTime.UtcNow; if(to<from)return Results.BadRequest("toUtc must be greater than or equal to fromUtc."); var lines=await db.OrderItems.AsNoTracking().Where(x=>db.Orders.Any(o=>o.Id==x.PosOrderId&&o.CreatedAtUtc>=from&&o.CreatedAtUtc<=to&&o.Status!="Cancelled")).ToListAsync(); var inv=await db.ProductInventories.AsNoTracking().ToDictionaryAsync(x=>x.ProductId); var rows=lines.GroupBy(x=>new{x.ProductId,x.ProductName}).Select(g=>{var revenue=g.Sum(x=>x.LineTotal);var quantity=g.Sum(x=>x.Quantity);var cost=g.Sum(x=>x.Quantity*x.UnitCost); if(cost==0&&inv.TryGetValue(g.Key.ProductId,out var i)) cost=quantity*i.AverageCost; return new{productId=g.Key.ProductId,productName=g.Key.ProductName,quantity,revenue=Math.Round(revenue,2),estimatedCost=Math.Round(cost,2),grossProfit=Math.Round(revenue-cost,2),marginPercent=revenue==0?0m:Math.Round((revenue-cost)/revenue*100m,2)};}).OrderByDescending(x=>x.revenue).Take(500).ToList(); var revenueTotal=rows.Sum(x=>x.revenue);var costTotal=rows.Sum(x=>x.estimatedCost);return Results.Ok(new{fromUtc=from,toUtc=to,revenue=Math.Round(revenueTotal,2),estimatedCost=Math.Round(costTotal,2),grossProfit=Math.Round(revenueTotal-costTotal,2),marginPercent=revenueTotal==0?0m:Math.Round((revenueTotal-costTotal)/revenueTotal*100m,2),products=rows}); }).RequireAuthorization(p=>p.RequireRole("Owner","Manager","Admin"));
  app.MapGet("/api/reports/pnl", async (CoreDbContext db, DateTime? fromUtc, DateTime? toUtc, string? groupBy) => { var from=fromUtc??DateTime.UtcNow.Date.AddDays(-29); var to=toUtc??DateTime.UtcNow; if(to<from)return Results.BadRequest("toUtc must be greater than or equal to fromUtc."); var mode=string.Equals(groupBy,"month",StringComparison.OrdinalIgnoreCase)?"month":"day"; var orders=await db.Orders.AsNoTracking().Where(x=>x.CreatedAtUtc>=from&&x.CreatedAtUtc<=to&&x.Status!="Cancelled").Select(x=>new{x.Id,x.CreatedAtUtc,x.Total}).ToListAsync(); var lines=await db.OrderItems.AsNoTracking().Where(x=>db.Orders.Any(o=>o.Id==x.PosOrderId&&o.CreatedAtUtc>=from&&o.CreatedAtUtc<=to&&o.Status!="Cancelled")).Select(x=>new{x.PosOrderId,x.Quantity,x.UnitCost}).ToListAsync(); var orderDates=orders.ToDictionary(x=>x.Id,x=>x.CreatedAtUtc); var sales=orders.GroupBy(x=>mode=="month"?new DateTime(x.CreatedAtUtc.Year,x.CreatedAtUtc.Month,1):x.CreatedAtUtc.Date).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Total)); var costs=lines.GroupBy(x=>mode=="month"?new DateTime(orderDates[x.PosOrderId].Year,orderDates[x.PosOrderId].Month,1):orderDates[x.PosOrderId].Date).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Quantity*x.UnitCost)); var expenses=await db.Expenses.AsNoTracking().Where(x=>x.ExpenseDateUtc>=from&&x.ExpenseDateUtc<=to).ToListAsync(); var expenseTotals=expenses.GroupBy(x=>mode=="month"?new DateTime(x.ExpenseDateUtc.Year,x.ExpenseDateUtc.Month,1):x.ExpenseDateUtc.Date).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Amount)); var periods=sales.Keys.Union(costs.Keys).Union(expenseTotals.Keys).OrderBy(x=>x).Select(period=>{var revenue=Math.Round(sales.GetValueOrDefault(period),2);var cost=Math.Round(costs.GetValueOrDefault(period),2);var expense=Math.Round(expenseTotals.GetValueOrDefault(period),2);var gross=Math.Round(revenue-cost,2);return new{period=mode=="month"?period.ToString("yyyy-MM"):period.ToString("yyyy-MM-dd"),revenue,cost,grossProfit=gross,operatingExpenses=expense,netProfit=Math.Round(gross-expense,2),marginPercent=revenue==0?0m:Math.Round((gross-expense)/revenue*100m,2)};}).ToList(); return Results.Ok(new{fromUtc=from,toUtc=to,groupBy=mode,totalRevenue=Math.Round(periods.Sum(x=>x.revenue),2),totalCost=Math.Round(periods.Sum(x=>x.cost),2),grossProfit=Math.Round(periods.Sum(x=>x.grossProfit),2),operatingExpenses=Math.Round(periods.Sum(x=>x.operatingExpenses),2),netProfit=Math.Round(periods.Sum(x=>x.netProfit),2),periods}); }).RequireAuthorization(p=>p.RequireRole("Owner","Manager","Admin"));
  app.MapGet("/api/reports/cash-flow", async (CoreDbContext db, DateTime? fromUtc, DateTime? toUtc, string? groupBy) => { var from=fromUtc??DateTime.UtcNow.Date.AddDays(-29); var to=toUtc??DateTime.UtcNow; if(to<from)return Results.BadRequest("toUtc must be greater than or equal to fromUtc."); var mode=string.Equals(groupBy,"month",StringComparison.OrdinalIgnoreCase)?"month":"day"; var payments=await db.Payments.AsNoTracking().Where(x=>x.CreatedAtUtc>=from&&x.CreatedAtUtc<=to&&x.Status=="Paid").ToListAsync(); var expenses=await db.Expenses.AsNoTracking().Where(x=>x.ExpenseDateUtc>=from&&x.ExpenseDateUtc<=to).ToListAsync(); var purchases=await db.PurchaseOrderItems.AsNoTracking().Where(x=>db.PurchaseOrders.Any(o=>o.Id==x.PurchaseOrderId&&o.CreatedAtUtc>=from&&o.CreatedAtUtc<=to)).ToListAsync(); var purchaseDates=await db.PurchaseOrders.AsNoTracking().Where(x=>x.CreatedAtUtc>=from&&x.CreatedAtUtc<=to).Select(x=>new{x.Id,x.CreatedAtUtc}).ToDictionaryAsync(x=>x.Id,x=>x.CreatedAtUtc); DateTime Key(DateTime d)=>mode=="month"?new DateTime(d.Year,d.Month,1):d.Date; var inflow=payments.GroupBy(x=>Key(x.CreatedAtUtc)).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.AmountPaid)); var expenseOut=expenses.GroupBy(x=>Key(x.ExpenseDateUtc)).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Amount)); var purchaseOut=purchases.GroupBy(x=>Key(purchaseDates[x.PurchaseOrderId])).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.QuantityReceived*x.UnitCost)); var periods=inflow.Keys.Union(expenseOut.Keys).Union(purchaseOut.Keys).OrderBy(x=>x).Select(k=>{var i=Math.Round(inflow.GetValueOrDefault(k),2);var e=Math.Round(expenseOut.GetValueOrDefault(k),2);var p=Math.Round(purchaseOut.GetValueOrDefault(k),2);return new{period=mode=="month"?k.ToString("yyyy-MM"):k.ToString("yyyy-MM-dd"),cashIn=i,purchases=p,expenses=e,netCashFlow=Math.Round(i-p-e,2)};}).ToList(); return Results.Ok(new{fromUtc=from,toUtc=to,groupBy=mode,totalCashIn=Math.Round(periods.Sum(x=>x.cashIn),2),totalPurchases=Math.Round(periods.Sum(x=>x.purchases),2),totalExpenses=Math.Round(periods.Sum(x=>x.expenses),2),netCashFlow=Math.Round(periods.Sum(x=>x.netCashFlow),2),periods}); }).RequireAuthorization(p=>p.RequireRole("Owner","Manager","Admin"));
 }
}
